      ],
      "paragraph_starts": [
        {"text": "Histoire de la folie à l'âge classique, qui fait sensation. Aucune référence", "continues_from_previous": false, "continues_to_next": false},
        {"text": "Jean Beaufret va peu à peu s'apercevoir qu'il n'est plus au centre", "continues_from_previous": false, "continues_to_next": false}
